function property(value: unknown, key: string): unknown {
  if ((typeof value !== "object" || value === null) && typeof value !== "function") {
    return undefined;
  }
  return Object.prototype.hasOwnProperty.call(value, key)
    ? (value as Record<string, unknown>)[key]
    : undefined;
}

function traverse(value: unknown, parts: string[]): unknown {
  for (const part of parts) {
    value = property(value, part);
    if (value === undefined) break;
  }
  return value;
}

function resolve(path: string, context: Context): unknown {
  const parts = path.split(".");
  if (parts[0] === "this") return traverse(context.current, parts.slice(1));
  if (parts[0] === "@index") {
    return parts.length === 1 ? context.index : traverse(context.index, parts.slice(1));
  }

  const local = traverse(context.current, parts);
  if (local !== undefined) return local;
  return context.current === context.root ? local : traverse(context.root, parts);
}

function truthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return value !== "" && value !== 0 && value !== false && value != null;
}

function scalar(value: unknown, node: InterpolationNode): string {
  if (value == null) return "";
  switch (typeof value) {
    case "string":
    case "number":
    case "boolean":
    case "bigint":
      return String(value);
    default:
      throw error(`Cannot render non-scalar value at \"${node.path}\"`, node.position);
  }
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], context: Context): string {
  let output = "";
  for (const node of nodes) {
    if (node.type === "text") {
      output += node.value;
    } else if (node.type === "interpolation") {
      const value = scalar(resolve(node.path, context), node);
      output += node.escaped ? escapeHtml(value) : value;
    } else if (node.type === "if") {
      const branch = truthy(resolve(node.path, context)) ? node.truthy : node.falsy;
      output += renderNodes(branch, context);
    } else {
      const value = resolve(node.path, context);
      if (Array.isArray(value) && value.length > 0) {
        for (let index = 0; index < value.length; index++) {
          output += renderNodes(node.truthy, {
            root: context.root,
            current: value[index],
            index,
          });
        }
      } else {
        output += renderNodes(node.falsy, context);
      }
    }
  }
  return output;
}

/** Render a Mini Template string with the supplied data. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { root: data, current: data, index: undefined });
}
import { render } from "./engine";

async function main(): Promise<void> {
  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra.length > 0) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  process.stdout.write(render(template, data));
}

try {
  await main();
} catch (cause) {
  const message = cause instanceof Error ? cause.message : String(cause);
  process.stderr.write(`mini-template: ${message}\n`);
  process.exitCode = 1;
}
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine";

describe("interpolation", () => {
  test("escapes HTML and supports raw values and missing values", () => {
    expect(render(`{{value}}|{{{value}}}|{{missing}}`, { value: `&<>\"'` }))
      .toBe(`&amp;&lt;&gt;&quot;&#39;|&<>\"'|`);
  });

  test("rejects non-scalar values", () => {
    expect(() => render("before {{value}}", { value: {} }))
      .toThrow(/Cannot render non-scalar value.*line 1, column 8/);
  });
});

describe("blocks", () => {
  test("implements the specified truthiness", () => {
    for (const value of ["", 0, false, null, undefined, []]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("no");
    }
    for (const value of ["x", 1, true, {}, [0]]) {
      expect(render("{{#if value}}yes{{else}}no{{/if}}", { value })).toBe("yes");
    }
  });

  test("supports nested each, root fallback, this, and index", () => {
    const template = "{{#each groups}}[{{name}}/{{title}}:{{#each this.items}}{{@index}}={{this}};{{else}}empty{{/each}}]{{else}}none{{/each}}";
    const data = {
      title: "root",
      groups: [
        { name: "a", items: ["x", "y"] },
        { name: "b", items: [] },
      ],
    };
    expect(render(template, data)).toBe("[a/root:0=x;1=y;][b/root:empty]");
  });

  test("preserves whitespace and removes comments", () => {
    expect(render(" a\n{{! ignored }}\t b ", {})).toBe(" a\n\t b ");
  });
});

describe("syntax errors", () => {
  test.each([
    ["{{#wat x}}", /Unknown block.*line 1, column 1/],
    ["x\n{{else}}", /else outside.*line 2, column 1/],
    ["{{#if x}}{{else}}{{else}}{{/if}}", /Duplicate else.*column 18/],
    ["{{#if x}}{{/each}}", /Mismatched closing block.*column 10/],
    ["{{#each x}}", /Unclosed each block.*column 1/],
    ["{{value", /Unclosed tag.*column 1/],
  ])("reports a useful position for %s", (template, pattern) => {
    expect(() => render(template as string, {})).toThrow(pattern as RegExp);
  });
});
# Mini Template

A small, dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{user.name}}!", { user: { name: "Ada" } });
```

`{{path}}` HTML-escapes values and `{{{path}}}` emits raw scalar text. The
engine supports nested `if` and `each` blocks with optional `else` branches,
comments (`{{! ... }}`), `{{this}}`, and `{{@index}}`. Inside loops, ordinary
paths first inspect the current item and then fall back to the root data.

```text
{{#each users}}{{@index}}: {{name}}{{else}}No users{{/each}}
{{#if enabled}}on{{else}}off{{/if}}
```

Run the CLI with UTF-8 template and JSON files:

```sh
bun run src/cli.ts template.txt data.json
```

Rendered text is the only stdout output. Syntax, file, JSON, and rendering
errors are written to stderr with a non-zero exit status.

Run the self-tests with `bun test`.

